 $items=$b['items']??[];if(!is_array($items)||!count($items)||count($items)>50)fail('Adicione peças à sacola.');$catalog=array_column(loadDoc('products'),null,'id');$lines=[];$cents=0;$counts=[];foreach($items as $item){$p=$catalog[$item['id']??'']??null;$size=textValue($item['size']??'',20);$qty=$item['quantity']??0;if(!$p||!$p['active']||!is_int($qty)||$qty<1||$qty>100)fail('Produto ou quantidade inválida.');$counts[$p['id'].':'.$size]=($counts[$p['id'].':'.$size]??0)+$qty;if(($p['stock'][$size]??0)<$counts[$p['id'].':'.$size])fail('O estoque desta peça mudou. Revise sua sacola.');$cents+=(int)round($p['price']*100)*$qty;$lines[]=['id'=>$p['id'],'name'=>$p['name'],'size'=>$size,'quantity'=>$qty,'price'=>$p['price'],'image'=>$p['image'],'nicks'=>cleanItemNicks($item),'nick'=>cleanItemNick($item),'custom'=>$item['custom']??null];}
