 $pricing=cartPricing($items,textValue($b['coupon']??'',40));foreach($lines as &$line)if(!empty($line['custom']))$line['price']=round($line['price']+(loadDoc('settings')['personalization_price']??0),2);unset($line);$token=bin2hex(random_bytes(32));$order=['id'=>$id,'status'=>'Recebido','payment_status'=>'approved_simulated','demo'=>true,'customer'=>$clean,'items'=>$lines,'subtotal'=>$pricing['subtotal'],'discount'=>$pricing['discount'],'gift'=>$pricing['gift'],'shipping'=>$shipping,'total'=>round($pricing['net']+$shipping['price'],2),'method'=>($b['method']??'pix')==='card'?'Cartão (simulado)':'Pix (simulado)','created'=>date('c'),'timeline'=>[['status'=>'Pagamento aprovado (teste)','time'=>date('c'),'source'=>'Simulação']]];$q=$db->prepare('INSERT INTO demo_orders(id,data,created,token_hash) VALUES(?,?,?,?)');$q->execute([$id,json_encode($order,JSON_UNESCAPED_UNICODE),date('c'),hash('sha256',$token)]);orderEmail($order,'payment_approved',$id.':approved','http://127.0.0.1:8080/acompanhar/#'.$token);reply(['order'=>$order,'token'=>$token,'email_preview'=>['to'=>$clean['email'],'subject'=>'[TESTE] Compra confirmada · '.$id,'body'=>'Olá, '.$clean['name'].'. Sua compra de teste '.$id.' foi aprovada automaticamente. Total: R$ '.number_format($order['total'],2,',','.').'. Nenhum valor foi cobrado. Acompanhe pelo link de teste e crie sua senha se desejar.']]);
