 if($action==='demo-account'){$password=textValue($b['password']??'',300);if(!$hash){if(strlen($password)<12)fail('Use uma senha com pelo menos 12 caracteres.');$q=$db->prepare('INSERT INTO demo_accounts(email,password) VALUES(?,?)');$q->execute([$email,password_hash($password,PASSWORD_DEFAULT)]);}else{if(!password_verify($password,$hash))fail('Senha incorreta.',401);}session_regenerate_id(true);$_SESSION['demo_customer']=$email;$authenticated=true;}
